insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.obligatory.reasons[0].cites[1].references[0].hadith', '38');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.obligatory.reasons[0].cites[0].quote', 'An gina Musulunci a kan abubuwa biyar: shahada cewa babu abin bautar da ya cancanta sai Allah, kuma Muhammad Manzon Allah ne, kafa salla, bayar da zakka, yin Hajji, da azumin Ramadan.');
