insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.prohibiting.reasons[1].id', 'fasting-reason-tashriq');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.prohibiting.reasons[1].title', 'Kwanakin Tashriq');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].intro', 'Abu Ubaid (ra) ya ruwaito:');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].quote', 'Na halarci Idin tare da Umar, sai ya fara da salla kafin hutba, saʼan nan ya ce: Manzon Allah (SAW) ya hana azumi a waɗannan kwanaki biyu; game da Idin Adha, kuna cin naman hadin ku, kuma game da Idin Fitr, shi ne karyewar azuminku.');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].references[1].collection', 'ibnmajah');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].references[1].hadith', '1722');
