insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].references[0].hadith', '2416');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].intro', 'Abu Huraira (ra) ya ruwaito:');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].quote', 'An hana azumi biyu: azumi ranar Idin Fitr da azumi ranar Idin Adha.');
