insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.ics-title', 'Dalilin azumi na son rai');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[1].cites[0].intro', 'Abu Qatada (ra) ya ruwaito cewa Manzon Allah Muhammad (SAW) ya ce:');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[1].cites[0].quote', 'Ina fatan daga Allah cewa azumi a Ranar Arafah zai rufe zunubobin shekara da ta gabata da na shekara da ke zuwa, kuma azumi a Ranar Ashura zai rufe zunubobin shekara da ta gabata.');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[1].cites[0].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[1].cites[0].references[0].hadith', '1162');
