insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[1].id', 'fasting-reason-arafah-or-ashura');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[1].title', 'Ranakun Arafah da Ashura');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[2].cites[0].intro', 'Daya daga cikin matan Annabi Muhammad (SAW) ta ce:');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[2].cites[0].quote', 'Manzon Allah Muhammad (SAW) ya kasance yana yin azumi a kwanaki tara na farko na Zulhijja, da Ranar Ashura, da kwanaki uku na kowane wata.');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[1].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[1].hadith', '2417');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[0].collection', 'abudawud');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[0].hadith', '2437');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[2].id', 'fasting-reason-first-9-dhu-al-hijjah');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[2].title', 'Kwanaki tara na farko na Zulhijja');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[1].intro', 'Abdullah bin Amr bin Al-As (ra) ya ruwaito:');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[1].quote', 'Ya isa ka yi azumi kwanaki uku a kowane wata, domin lada mai kyau tana ninka sau goma, don haka zai zama kamar azumin shekara gaba ɗaya.');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[1].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[1].references[0].hadith', '1975');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[2].intro', 'Abu Qatada (ra) ya ruwaito cewa Manzon Allah (SAW) ya ce:');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[2].quote', 'Azumi kwanaki uku a kowane wata, da azumin Ramadan a kowane shekara, shi ne azumi na dindindin.');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[2].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[2].references[0].hadith', '1162');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[3].intro', 'Manzon Allah (SAW) ya ce wa Abu Dharr (ra):');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[3].quote', 'Azumi kwanaki uku a kowane wata kamar azumi ne na rayuwa gaba ɗaya.');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[3].references[0].collection', 'ibnmajah');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[3].references[0].hadith', '1708');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[4].intro', 'An ruwaito daga Jarir bin Abdullah (ra) cewa Manzon Allah (SAW) ya ce:');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[4].quote', 'Azumi kwanaki uku a kowane wata azumi ne na rayuwa gaba ɗaya, kuma kwanakin Al-Bid masu haske su ne na sha uku, sha huɗu da sha biyar.');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[4].references[0].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[4].references[0].hadith', '2420');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[5].intro', 'Abu Huraira (ra) ya ruwaito:');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[5].quote', 'Abina na kusa (Manzon Allah Muhammad (SAW)) ya ba ni shawara kan abubuwa uku: in yi azumi kwanaki uku a kowane wata, in yi salla rakaʼa biyu na Duha, in kuma yi salla Witir kafin in barci.');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[5].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[5].references[0].hadith', '1981');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[6].intro', 'Abu Al-Darda (ra) ya ruwaito:');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[6].quote', 'Abina (Manzon Allah (SAW)) ya umarce ni da in riƙe ayyuka uku da ba na barin su: ya umarce ni da azumi kwanaki uku a kowane wata.');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].collection', 'abudawud');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].hadith', '1433');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[0].intro', 'Annabi Muhammad (SAW) ya ba Abu Dharr (ra) shawara:');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[0].quote', 'Idan ka yi azumi a wani bangare na wata, to ka yi azumi kwanaki na sha uku, sha huɗu da sha biyar.');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[0].references[0].collection', 'tirmidhi');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].cites[0].references[0].hadith', '761');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].id', 'fasting-reason-white-days');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[3].title', 'Kwanakin Fari');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[1].intro', 'Usamah bin Zaid (ra) ya ruwaito cewa Manzon Allah (SAW) ya ce:');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[1].quote', 'Waɗannan kwanaki biyu ne da ake gabatar da ayyuka ga Ubangijin talikai, ina kuma ina son a gabatar da aikina ina cikin azumi.');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[1].references[0].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[1].references[0].hadith', '2358');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[2].intro', 'Abu Qatada Al-Ansari (ra) ya ruwaito cewa an tambayi Manzon Allah (SAW) game da azumi a Litinin, sai ya ce:');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[2].quote', 'Ita ce ranar da aka haife ni, kuma ita ce ranar da aka naɗa ni Annabi ko aka sauko mini da wahayi.');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[2].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[2].references[0].hadith', '1162b');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[3].intro', 'Aisha (ra) ta ruwaito:');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[3].quote', 'Annabi (SAW) ya kasance yana neman yin azumi a Litinin da Alhamis.');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[3].references[0].collection', 'tirmidhi');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[3].references[0].hadith', '745');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[0].intro', 'Abu Huraira (ra) ya ruwaito cewa Manzon Allah (SAW) ya ce:');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[0].quote', 'Ana gabatar da ayyuka a Litinin da Alhamis, ina kuma ina son a gabatar da aikina ina cikin azumi.');
insert into i18n_bundles (locale, code, value) values ('ha', 'fasting.reason-groups.voluntary.reasons[4].cites[0].references[1].collection', 'riyadussalihin');
